This will add permissions for everyone (`S-1-1-0`) to start, stop, read and delete the rainway service that is created by the bootstrapper.

Right now this only happens on service install rather than service start, but could happen in both cases instead.

I tested this in a seperate rust project working on the rainwayradar service as follows:
```rust
use std::ptr;

extern crate winapi;
extern crate windows_acl;

use windows_acl::acl::ObjectType;
use windows_acl::acl::ACL;
use windows_acl::helper::{current_user, name_to_sid, string_to_sid};

use winapi::um::winnt;
use winapi::um::winnt::PSID;
use winapi::um::winsvc;

// CustomServiceManager is a simple clone of the windows_service service manager
// but we can acutally access the manager_handle in this case
pub struct CustomServiceManager {
    manager_handle: winsvc::SC_HANDLE,
}

impl CustomServiceManager {
    // create a new CustomServiceManager
    // This will always open a service manager for the current machine with all access
    pub fn new() -> Result<Self, &'static str> {
        let handle = unsafe {
            winsvc::OpenSCManagerW(ptr::null(), ptr::null(), winsvc::SC_MANAGER_ALL_ACCESS)
        };

        if handle.is_null() {
            Err("Service connection failure")
        } else {
            Ok(CustomServiceManager {
                manager_handle: handle,
            })
        }
    }

    // change_service_dacl will change the dacl for the given service
    // allowing it to be started, stopped and modified by any user on the system
    pub fn change_service_dacl(&self, service: &str) -> Result<(), &str> {
        // get the service by name
        let svc_handle = unsafe {
            winsvc::OpenServiceW(
                self.manager_handle,
                to_wstring(service).as_ptr(),
                winnt::READ_CONTROL | winnt::WRITE_DAC,
            )
        };

        if svc_handle.is_null() {
            // we coudlnt find the service
            println!("Unable to find service");
            return Err("Service missing");
        }

        let sid = if let Ok(sid) = string_to_sid("S-1-1-0") {
            sid
        } else {
            return Err("current user failed");
        };

        println!("0x{:X}", svc_handle as u64);

        let mut acl = match ACL::from_handle(
            svc_handle as winnt::HANDLE,
            winapi::um::accctrl::SE_SERVICE,
            false,
        ) {
            Ok(acl) => acl,
            Err(e) => {
                println!("Server query failed {}", e);
                return Err("Server query failed");
            }
        };

        match acl.allow(
            sid.as_ptr() as PSID,
            false,
            winsvc::SERVICE_START | winsvc::SERVICE_STOP | winnt::READ_CONTROL | winnt::DELETE,
        ) {
            Ok(status) => {
                if !status {
                    Err("sid update failed")
                } else {
                    println!("allowed successfully");
                    Ok(())
                }
            }
            Err(code) => {
                println!("Failed to allow {}", code);
                Err("sid update failed")
            }
        }
    }
}

impl Drop for CustomServiceManager {
    fn drop(&mut self) {
        unsafe {
            winsvc::CloseServiceHandle(self.manager_handle);
        }
    }
}

fn to_wstring(value: &str) -> Vec<u16> {
    use std::os::windows::ffi::OsStrExt;

    std::ffi::OsStr::new(value)
        .encode_wide()
        .chain(std::iter::once(0))
        .collect()
}

fn main() {
    let manager = match CustomServiceManager::new() {
        Ok(m) => m,
        Err(e) => {
            println!("{}", e);
            return;
        }
    };

    if let Err(e) = manager.change_service_dacl("RainwayRadar") {
        println!("{}", e);
        return;
    };

    println!("Hello, world!");
}
```

with these 2 dependencies
```toml
winapi = { version = "0.3.8", features = ["winuser", "tlhelp32", "handleapi", "restartmanager", "winsvc"] }
windows-acl = { git = "https://github.com/trailofbits/windows-acl", branch = "master" }
```

